#!/usr/bin/env python3
"""Simple LSP client harness for probing the rustowl binary."""
import json
import subprocess
import sys
import threading
import time
import os

BIN = os.environ.get("RUSTOWL_BIN", "/workspace/executable")


class Client:
    def __init__(self, args=None, cwd=None, env=None, binpath=None):
        args = args if args is not None else ["--stdio"]
        e = dict(os.environ)
        if env:
            e.update(env)
        self.p = subprocess.Popen(
            [binpath or BIN] + args,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=cwd,
            env=e,
        )
        self.msgs = []
        self.err = []
        self.lock = threading.Lock()
        self.t = threading.Thread(target=self._reader, daemon=True)
        self.t.start()
        self.te = threading.Thread(target=self._ereader, daemon=True)
        self.te.start()

    def _reader(self):
        f = self.p.stdout
        while True:
            headers = {}
            line = f.readline()
            if not line:
                return
            while line not in (b"\r\n", b"\n"):
                if not line:
                    return
                if b":" in line:
                    k, v = line.decode("utf8", "replace").split(":", 1)
                    headers[k.strip().lower()] = v.strip()
                line = f.readline()
                if not line:
                    return
            n = int(headers.get("content-length", 0))
            body = f.read(n)
            try:
                obj = json.loads(body)
            except Exception:
                obj = {"__raw__": body.decode("utf8", "replace")}
            with self.lock:
                self.msgs.append((time.time(), headers, obj))

    def _ereader(self):
        for line in self.p.stderr:
            with self.lock:
                self.err.append(line.decode("utf8", "replace").rstrip("\n"))

    def send(self, obj):
        body = json.dumps(obj, separators=(",", ":")).encode()
        self.p.stdin.write(b"Content-Length: %d\r\n\r\n" % len(body))
        self.p.stdin.write(body)
        self.p.stdin.flush()

    def send_raw(self, data: bytes):
        self.p.stdin.write(data)
        self.p.stdin.flush()

    def wait_id(self, id_, timeout=30):
        end = time.time() + timeout
